"""Vaccines review: artist evidence -> clear change -> a usable programme.
Run after updating the frozen research and authored strategic context together.
"""
import json,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'public/vaccines/research-2026-11-09.json').read_text());V={v['id']:v for v in D['videos']};S=[]
def esc(s):return html.escape(str(s),quote=True)
def k(x):return f'{x/1000:.1f}k' if x<1000000 else f'{x/1000000:.2f}m'
def img(i):return f'/vaccines/images/{i}.jpg' if (R/f'public/vaccines/images/{i}.jpg').exists() else f'https://i.ytimg.com/vi/{i}/hqdefault.jpg'
def photo(i,title=None,note='',frame=False):
 v=V[i];return f'<a class="photo {"frame" if frame else ""}" href="https://www.youtube.com/watch?v={i}" target="_blank" rel="noopener"><figure><img src="{img(i)}" alt="{esc(title or v["title"])}" loading="lazy" width="480" height="270"><figcaption><div class="value">{k(v["views"])} <span class="small">lifetime views ↗</span></div><div class="title">{esc(title or v["title"].replace("The Vaccines - ",""))}</div><div class="meta">{esc(note)}</div></figcaption></figure></a>'
def source(s):return '<p class="source">'+s+' · <a href="#analysis">Analysis</a></p>'
def label(s):return '<span class="label">'+s+'</span>'
def slide(id,title,body,theme=''):
 S.append(f'<section class="slide {theme}" id="{id}" data-title="{esc(title)}"><div class="inner">{body}</div><div class="folio"><span>The Vaccines × YouTube</span><span>{len(S)+1:02d} / The catalogue. The last campaign. What comes next.</span></div></section>')
slide('intro','Fifteen years in. What comes next?',f'''
<div class="cover-grid"><div>{label('Virgin Music Group · YouTube · 09.11.26')}<h1>The<br>Vaccines</h1><p class="serif cover-title">Fifteen years in.<br>What comes next?</p></div><figure class="cover-photo"><img src="{img('uQKjI6395iU')}" alt="The Vaccines in the red-lit If You Wanna video" width="720" height="405"><figcaption>If You Wanna, 2011. Start with the songs people already know.</figcaption></figure></div><div class="cover-meta"><p><b>Use the catalogue to reconnect. Build a fuller campaign around the new record.</b></p><span class="stamp">Working strategy · v2</span></div>
''','cover')
